#include "rocks/mesh.hpp"
#include <iostream>
#include <stdexcept>
using namespace rocks;
#define CHECK(x) do{if(!(x))throw std::runtime_error(#x);}while(0)
int main(){try{for(auto family:{"fractured_wall","irregular_beds","overhang"}){Recipe r;r.schemaVersion=2;r.generatorVersion="rocks-v3";r.family=family;r.extractorVersion="poly-csg-v1";r.wear=0;auto f=makeField(r);CHECK(!f.fractures.empty());auto noisy=r;noisy.detail=1;auto fn=makeField(noisy);CHECK(fn.fractures!=f.fractures);CHECK(fn.fractures==makeField(noisy).fractures);CHECK(validate(extractPolyhedral(fn,Stage::Stratified).mesh,r.size).accepted);for(double x:{-.3,0.,.3})for(double y:{-.2,0.,.2})CHECK(fieldValue(f,{x*r.size,y*r.size,-.3*r.size},Stage::Eroded)<0);for(int x=-6;x<=6;x++)for(int y=-6;y<=6;y++)for(int z=-6;z<=6;z++){Vec3 p{x*r.size/12,y*r.size/12,z*r.size/12};CHECK(fieldValue(f,p,Stage::Stratified)>=fieldValue(f,p,Stage::Base));}for(auto stage:{Stage::Base,Stage::Stratified,Stage::Eroded}){auto e=extractPolyhedral(f,stage);auto report=validate(e.mesh,r.size);std::cout<<family<<" direct-polyhedral "<<int(stage)<<" amb "<<e.ambiguousCells<<" bad "<<report.badEdges<<","<<report.badVertices<<" deg "<<report.degenerateFaces<<std::endl;CHECK(report.accepted);for(std::size_t i=0;i<e.mesh.indices.size();i+=3){auto a=e.mesh.positions[e.mesh.indices[i]],b=e.mesh.positions[e.mesh.indices[i+1]],c=e.mesh.positions[e.mesh.indices[i+2]];auto p=(a+b+c)/3;auto normal=normalized(cross(b-a,c-a));CHECK(fieldValue(f,p+normal*(1e-7*r.size),stage)>0);CHECK(fieldValue(f,p-normal*(1e-7*r.size),stage)<0);}}}}catch(std::exception&e){std::cerr<<e.what()<<'\n';return 1;}}
